package com.ecommerce.commerceapi.inventory.domain; import com.ecommerce.commerceapi.products.domain.ProductVariant; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.*;
@Entity @Table(name="inventory_transactions") public class InventoryTransaction { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="variant_id",nullable=false) private ProductVariant variant; @Enumerated(EnumType.STRING) @Column(nullable=false) private InventoryTransactionType transactionType; @Column(nullable=false) private int quantity; private BigDecimal unitCost; private String referenceType,referenceId; private String notes; @Column(nullable=false) private LocalDate transactionDate; @Column(nullable=false,updatable=false) private Instant createdAt; @PrePersist void create(){createdAt=Instant.now();} public void setVariant(ProductVariant v){variant=v;}public void setTransactionType(InventoryTransactionType v){transactionType=v;}public void setQuantity(int v){quantity=v;}public void setUnitCost(BigDecimal v){unitCost=v;}public void setReferenceType(String v){referenceType=v;}public void setReferenceId(String v){referenceId=v;}public void setNotes(String v){notes=v;}public void setTransactionDate(LocalDate v){transactionDate=v;} public InventoryTransactionType getTransactionType(){return transactionType;}public int getQuantity(){return quantity;} }
